#include "metaHttpServiceObject.h"
#include "core/graphics/picture.h"   // ibPicture::FromBase64 — the master read, scaled to 16 once

/* PNG */
static const ibString s_httpService_16_png = ibT("");
static const ibString s_urlTemplate_16_png = ibT("");
static const ibString s_httpServiceMethod_16_png = ibT("");

ibPicture ibValueMetaObjectHttpService::GetIcon() const
{
	return GetIconGroup();
}

ibPicture ibValueMetaObjectHttpService::GetIconGroup()
{
	static const ibPicture picture = ibPicture::FromBase64(s_httpService_16_png, ibSize(16, 16));

	return picture;
}

ibPicture ibValueMetaObjectUrlTemplate::GetIcon() const
{
	return GetIconGroup();
}

ibPicture ibValueMetaObjectUrlTemplate::GetIconGroup()
{
	static const ibPicture picture = ibPicture::FromBase64(s_urlTemplate_16_png, ibSize(16, 16));

	return picture;
}

ibPicture ibValueMetaObjectHttpServiceMethod::GetIcon() const
{
	return GetIconGroup();
}

ibPicture ibValueMetaObjectHttpServiceMethod::GetIconGroup()
{
	static const ibPicture picture = ibPicture::FromBase64(s_httpServiceMethod_16_png, ibSize(16, 16));

	return picture;
}
